// biquote — free real-time market data client (https://biquote.io)
// Zero dependencies; uses global fetch (Node 18+ and every browser).
// No API key required. Anonymous quota: 15,000 requests/min per IP.

const DEFAULT_BASE = "https://biquote.io";

export class Biquote {
    /** @param {{ baseUrl?: string, apiKey?: string }} [opts] */
    constructor(opts = {}) {
        this.baseUrl = (opts.baseUrl ?? DEFAULT_BASE).replace(/\/$/, "");
        this.apiKey = opts.apiKey; // optional — the API is open without one
    }

    async #get(path, params) {
        const url = new URL(this.baseUrl + path);
        for (const [k, v] of Object.entries(params ?? {})) {
            if (v === undefined || v === null) continue;
            if (Array.isArray(v)) for (const item of v) url.searchParams.append(k, String(item));
            else url.searchParams.set(k, String(v));
        }
        const headers = this.apiKey ? { "X-API-Key": this.apiKey } : {};
        const res = await fetch(url, { headers });
        if (!res.ok) {
            const body = await res.text().catch(() => "");
            throw new Error(`biquote ${res.status} ${path}: ${body.slice(0, 200)}`);
        }
        return res.json();
    }

    /**
     * Latest quote for one symbol. Use `mid` as the price — `last`/`volume`
     * are always 0 on a CFD feed.
     *
     * When the market is closed you get the last known price, not an error.
     * Every response carries `marketState` ("open" | "closed"), `stale` and
     * `quoteAgeSeconds`, so check one before showing a number as current:
     *
     *     const t = await bq.tick("EURUSD");
     *     if (t.marketState === "closed") show(t.mid, "market closed");
     *     else                            show(t.mid, `${t.dayDiffPercent}%`);
     *
     * Pass `{ allowStale: false }` for the strict behaviour — throws as soon
     * as a quote is over five minutes old, which is what a trading client
     * wants. Either way it throws for an unknown symbol, or one that has not
     * quoted in over seven days.
     */
    tick(symbol, { allowStale } = {}) {
        return this.#get(`/api/${encodeURIComponent(symbol.toUpperCase())}`, { allowStale });
    }

    /** Latest quotes for up to 100 symbols in one request, keyed by symbol. */
    latest(symbols, { allowStale } = {}) {
        return this.#get("/api/latest", { symbols: symbols.map(s => s.toUpperCase()), allowStale });
    }

    /** OHLC bars. Returns the bars array (oldest first). Intervals: 1m 5m 15m 30m 1h 4h 1d. */
    async ohlc(symbol, { interval = "1h", limit = 100, from, to } = {}) {
        const env = await this.#get(`/api/${encodeURIComponent(symbol.toUpperCase())}/ohlc`,
            { interval, limit, from, to });
        return (env.bars ?? []).slice().reverse(); // API sends newest-first
    }

    /**
     * Symbol catalogue.
     *
     * `liveOnly` means "quoting this second", so it empties out for FX and
     * equities the moment their market closes. For anything that has to stay
     * stable — a picker, a nav menu, a cached list — use
     * `quotedWithinDays: 7` instead.
     */
    symbols({ liveOnly, quotedWithinDays, activeOnly, type, exchange, source } = {}) {
        return this.#get("/api/symbols", { liveOnly, quotedWithinDays, activeOnly, type, exchange, source });
    }

    /** Metadata for one symbol: description, type, exchange, digits, tick size. */
    symbol(name) { return this.#get(`/api/symbols/${encodeURIComponent(name.toUpperCase())}`); }

    /** Search symbols by name or description. */
    search(q, { liveOnly, limit } = {}) { return this.#get("/api/symbols/search", { q, liveOnly, limit }); }

    /** Symbols currently receiving ticks, with description/type/exchange. */
    active() { return this.#get("/api/active"); }

    /** Top gainers / losers (period: 1H 4H 1D 1W) and today's biggest movers. */
    gainers(opts = {}) { return this.#get("/api/market/gainers", opts); }
    losers(opts = {}) { return this.#get("/api/market/losers", opts); }
    mostActive(opts = {}) { return this.#get("/api/market/most-active", opts); }
    marketSummary(opts = {}) { return this.#get("/api/market/summary", opts); }

    /** Economic calendar — 54 countries, actual/forecast/previous. */
    calendar(opts = {}) { return this.#get("/api/calendar", opts); }
    calendarUpcoming(opts = {}) { return this.#get("/api/calendar/upcoming", opts); }
    calendarCountries() { return this.#get("/api/calendar/countries"); }

    /**
     * News. `kind` is one of market | crypto | technology | hn, or pass
     * `{ q }` to search. The market, crypto and technology feeds mix in
     * Hacker News stories; `hn` is Hacker News alone.
     */
    news(kind = "market", opts = {}) {
        if (kind === "search") return this.#get("/api/news/search", opts);
        return this.#get(`/api/news/${encodeURIComponent(kind)}`, opts);
    }
}

export default Biquote;
